function wooCommerceMauticFields({ customer }) {
  if (customer == null || typeof customer !== 'object' || Array.isArray(customer)) throw new Error('Expected a WooCommerce customer object');
  const email = typeof customer.email === 'string' ? customer.email.trim() : '';
  if (!/^[^\s@:"\\]+@[^\s@:"\\]+$/.test(email) || email.length > 254) throw new Error('Customer email is missing or invalid');
  const text = (value, field) => { if (value == null) return ''; if (typeof value !== 'string') throw new Error('Customer ' + field + ' must be text'); return value; };
  const firstname = text(customer.first_name, 'first name'), lastname = text(customer.last_name, 'last name'), company = text(customer.billing?.company, 'billing company');
  return { search: email, email, createFields: { email, firstname, lastname, company, position: '', title: '' }, updateFields: { firstname, lastname } };
}

return $input.all().map((item, index) => ({ json: wooCommerceMauticFields({ customer: item.json }), pairedItem: { item: index } }));

function mauticCustomerMatch({ contacts, email }) {
  if (!Array.isArray(contacts)) throw new Error('Mautic contact search did not return an array');
  if (contacts.length >= 30) throw new Error('Mautic search filled the 30-contact source window; narrow the data before retrying');
  const matches = contacts.filter(contact => typeof contact?.fields?.all?.email === 'string' && contact.fields.all.email.trim().toLowerCase() === email.toLowerCase());
  if (matches.length > 1) throw new Error('More than one Mautic contact has the customer email');
  if (matches.length === 0 && contacts.length > 0) throw new Error('Mautic search returned contacts without an exact customer email match');
  const matched = matches[0] ?? null;
  if (matched != null && (!Number.isSafeInteger(matched.id) || matched.id <= 0)) throw new Error('Matched Mautic contact ID is invalid');
  return { create: matched == null, matched };
}

const prepared = $("Prepare customer fields").first().json;
const contacts = $input.all().map(item => item.json).filter(contact => Object.keys(contact).length > 0);
const decision = mauticCustomerMatch({ contacts, email: prepared.email });
return [{ json: { ...prepared, ...decision } }];

function mauticContactSaved({ contact }) {
  if (!contact || typeof contact !== 'object' || Array.isArray(contact) || !Number.isInteger(contact.id) || contact.id <= 0) {
    throw new Error('Mautic did not return a saved contact ID');
  }
  return { contact };
}

return { json: mauticContactSaved({ contact: $json }).contact };
